def reading_step(rid):
    r = RD[rid]
    return f"קוראים בקול:\n\n״{r['title']}״\n\n{r['text']}"


def game_step(gid, how, after):
    g = G[gid]
    return f"״{g['name']}״ (משחק מוכר, בלי קישור לנושא).\n\n{g['description']}\n\n{how}\n\nאחרי המשחק שואלים: {after}"


def make(a):
    t = a['times']
    flow = [
        {'label': f'פתיחה ({t[0]} דק׳)', 'body': a['opening']},
        {'label': f'משחק ({t[1]} דק׳)', 'body': game_step(a['game'], a['game_how'], a['game_after'])},
        {'label': f'מתודה ({t[2]} דק׳)', 'body': a['method']},
    ]
    for label, body, mins in a.get('extras', []):
        flow.append({'label': f'{label} ({mins} דק׳)', 'body': body})
    flow.append({'label': f'קטע קריאה ({t[3]} דק׳)', 'body': reading_step(a['reading'])})
    if a.get('reading2'):
        flow.append({'label': f"קטע קריאה נוסף ({a['time2']} דק׳)", 'body': reading_step(a['reading2'])})
    flow += [
        {'label': f'דיון ({t[4]} דק׳)', 'items': a['discussion']},
        {'label': f'הסבר ({t[5]} דק׳)', 'body': a['explain']},
        {'label': f'סיכום ({t[6]} דק׳)', 'body': a['summary']},
    ]
    return dict(id=a['id'], title=a['title'], categorySlug='activities', subtopics=a['subtopics'], ageLabel=age_label(a['ageMin'], a['ageMax']),
        ageMin=a['ageMin'], ageMax=a['ageMax'], duration=sum(t) + a.get('time2', 0) + sum(e[2] for e in a.get('extras', [])), groupSize='8–25 חניכים', equipment=a.get('equipment', []), shabbat=a['shabbat'],
        place='פנים', energy=a['energy'], depth=a['depth'], values=a['values'], tags=a['tags'], rating=4.6, character='C', description=a['description'],
        goals=a['goals'], opening=a['opening'], game=game_step(a['game'], a['game_how'], a['game_after']), method='\n\n'.join([a['method']] + [e[1] for e in a.get('extras', [])]), discussion=a['discussion'],
        guideNotes=a.get('guide', ''), summary=a['summary'], tip=a['tip'], shabbatNote=a['shabbatNote'], flow=flow)


